+      'tap returns to the tail', (tester) async {
+    final service = _StreamingPagingService()
+      ..msgs = _msgs(60)
+      ..above = 0;
+    service.onLoadNewer = () async {
+      service
+        ..hasNewer = false
+        ..below = 0
+        ..streaming = false
+        ..notifyListeners();
+    };
