+
+    service
+      ..hasNewer = true
+      ..below = 55
+      ..notifyListeners();
+    await tester.pump();
+    expect(find.text('Load newer (55 more)'), findsOneWidget);
+    expect(service.loadNewerHistoryCalls, 0);
+
+    // The run ends while the user stays scrolled away: the plate stays
+    // (it is the only "you are in history" signal).
+    service
+      ..streaming = false
+      ..notifyListeners();
+    await tester.pump();
+    expect(find.text('Load newer (55 more)'), findsOneWidget);
