    _historyLoadError = e is StateError ? e.message : e.toString();
    notifyListeners();
  } finally {
    _loadingHistory = false;
    notifyListeners();
  }
}

/// Jump-to-message (issue #135 AC6,
/// [FaChatService.jumpToMessage]). Two mechanisms:
