      fsRevision.value++;
    }
    _persistSoon();
    final text = result.content
        .whereType<TextContent>()
        .map((b) => b.text)
        .join('\n');
    messages.add(
      FahChatMessage(
        role: 'tool',
        content: text,
        toolName: toolName,
        isError: isError,
