                WidgetsBinding.instance.platformDispatcher.locale,
              ).languageCode,
            )
          : message.errorMessage ?? 'Run failed (${StopReason.error.name})';
      error = text;
      messages.add(
        FahChatMessage(
          role: 'tool',
          content: text,
          toolName: 'error',
          isError: true,
        ),
      );
    } else if (message.stopReason == StopReason.aborted) {
      error = message.errorMessage ?? 'Run aborted';
    }
    _notify();
