+    // the user is parked at the bottom: the screen rejoins the tail on
+    // its own — the below-count never becomes a banner.
+    service
+      ..streaming = true
+      ..hasNewer = true
+      ..below = 3
+      ..notifyListeners();
+    await tester.pump();
