    messages.add(
      FahChatMessage(
        role: 'system',
        content: '[$toolName] ${_shortArgs(args)}',
      ),
    );
    _pushLiveActivityStatus();
    _notify();
  }

  void _onToolExecutionEnd({
    required String toolName,
    required ToolExecutionResult result,
    required bool isError,
  }) {
    _activeToolCalls--;
