  Future<(AgentService, CountingFileSystem)> loadedService(
    int count, {
    CountingFileSystem? countingFs,
    Agent Function()? agentBuilder,
  }) async {
    final tmp = await io.Directory.systemTemp.createTemp('fa_windowed');
