  void _onToolExecutionEnd({
    required String toolName,
    required ToolExecutionResult result,
    required bool isError,
  }) {
    _activeToolCalls--;
    _armIdleWatchdog();
    if (AgentService._kMutatingToolNames.contains(toolName)) {
