      _appendAssistantDelta(assistantMessageEvent.delta);
    } else if (assistantMessageEvent is ThinkingDeltaEvent) {
      _appendThinkingDelta(assistantMessageEvent.delta);
    }
  }

  void _onMessageEnd(Message message) {
