+  @override
+  int? get historyBelowCount => below;
+  @override
+  bool get historyLoading => loading;
+
+  @override
+  Future<void> loadNewerHistory() async {
+    loadNewerHistoryCalls++;
+    await onLoadNewer?.call();
+  }
