  /// Background record count (streams newlines, no JSON decode). The first
  /// call scans; later calls return the memo.
  Future<int> countRecords() async =>
      _totalRecords ??= await _reader.countRecords();

  /// File records above the window — the "Load earlier" banner count.
  /// `null` while unknown (background count running, or right after a
  /// [jumpToOffset] until an edge is walked); `0` at the file top.
  Future<int?> countAbove() async {
    if (_aboveCount case final known?) return known;
    if (!_hasOlder) return _aboveCount = 0;
    final below = _belowCount;
    if (below == null) return null;
    final total = await countRecords();
    return _aboveCount = total - _entries.length - below;
  }

  /// File records below the window — the "Load newer" banner count.
  /// `null` while unknown (after a [jumpToOffset]); `0` at the tail.
  int? get countBelow => _belowCount;

  /// Loads one chunk of records above the window. Returns the records
  /// that JOIN THE ACTIVE BRANCH, root-first — the transcript delta to
  /// prepend. Side-branch records in the chunk enter the index (id
  /// lookups) but are not returned. Reads chunks until a branch record
  /// lands (a chunk can be entirely foreign-branch), the branch root or
  /// file top is reached, or [maxChunks] passes. When the residency cap
  /// is exceeded the NEWEST side slides out — deep paging moves the
  /// window up; [loadNewer] (or [jumpToOffset]) brings the tail side
  /// back.
  Future<List<SessionRecord>> loadOlder({
    int maxRecords = defaultChunkRecords,
    int maxBytes = defaultChunkBytes,
    int maxChunks = 8,
  }) async {
    final joined = <SessionRecord>[];
    for (var pass = 0; pass < maxChunks; pass++) {
      final chunk = await _readOlderChunk(maxRecords, maxBytes);
      if (chunk == null) break;
      joined.addAll(_joinBranchUpward(chunk.$1, chunk.$2));
      if (joined.isNotEmpty || !_hasOlder) break;
    }
    _evictToBound(newestSide: true);
    return joined;
  }

  /// Pages older chunks until [found] matches a record on the active
  /// branch, the file top is reached, or [maxPages] pass — WITHOUT
  /// sliding the newest side out: the residency cap is suspended for the
  /// walk, so a resume keeps the tail anchored while reaching the
  /// compaction boundary (the CLI resume walks to the newest compaction
  /// — the old ensure path let [loadOlder] evict the leaf on the first
  /// chunk, the branch read empty, and every deep-boundary resume fell
  /// back to a full open: 10s+ on a marathon file).
  ///
  /// Returns whether the tail-anchored branch is intact after the walk;
  /// `false` only on [maxPages] exhaustion (the caller's documented
  /// full-open fallback). A session without a match pages everything —
  /// the whole chain is then resident and the walk reports `true`.
  ///
  /// [tokenBudget] (issue #503) adds a second stop condition: once the
  /// resident branch's estimated CONTEXT tokens reach the budget (only
  /// context-projecting records count — ledger payloads like
  /// `model_request_summary` count zero, see [estimateSessionBranchTokens]),
  /// the walk stops even without a match. A resume needs only what fits
  /// the model's context window; older history pages in lazily through
  /// the scrollback's [loadOlder] path. `null` keeps the pure
  /// match/file-head semantics.
  Future<bool> growOlderUntil(
    bool Function(SessionRecord record) found, {
    int maxPages = 512,
    int? tokenBudget,
  }) async {
    _suspendEviction = true;
    try {
      var pages = 0;
      // The walk pages in BLOCKS that double per page (chunk size → 2x →
      // …, capped): each strip is read, decoded and parsed exactly ONCE
      // (SessionChunkReader.readBlockBefore). The capped loadOlder path
      // re-decoded its doubling window on every pass — a 400 MB
      // tail-after-compaction cost 10s+ in redundant decode alone.
      var blockRecords = _chunkRecords;
      var blockBytes = _chunkBytes;
      while (pages < maxPages) {
        final leaf = await getLeafId();
        if (leaf == null) return true; // genuinely empty session
        final branch = await getPathToRoot(leaf);
        if (branch.any(found)) return true;
        if (tokenBudget != null) {
          // Projection-aware whole-branch estimate (issue #503 round 3b):
          // hidden/covered records project as one-line markers or nothing
          // at all, so the raw tally overshot the real context by ~8x on
          // structured-compaction marathons and tripped the budget far
          // too early (under-filled resume window). A whole-branch
          // recompute per page is a chars/4 fold — negligible next to the
          // page's decode — and unlike an incremental prefix tally it
          // sees the hiding markers, which sit LATER on the branch than
          // the records they hide.
