        await _reAnchorToTail();
        return (reanchored: true, delta: await _windowBranch());
      }
      return (reanchored: false, delta: const <SessionRecord>[]);
    }
    _fileSize = info.size;
    _fileMtimeMs = info.mtimeMs;
