      agent: agentBuilder?.call() ?? _createAgent(),
      env: LocalExecutionEnv(cwd: tmp.path),
      sessionsRoot: tmp.path,
      repo: JsonlSessionRepo(fs: counting, sessionsRoot: tmp.path),
      watchExternalSessions: false,
