  /// Largest single block of the [growOlderUntil] walk — the per-page
  /// doubling ceiling (64 MB / 4096 records keeps one page at ~300 ms and
  /// bounds the transient strip buffer).
  static const maxWalkBlockRecords = 4096;
  static const maxWalkBlockBytes = 64 << 20;

  /// Record-granular budget trim for the [growOlderUntil] stop (gh-968,
  /// AC-R4): un-indexes the OLDEST resident records down to the cut
  /// [projectedBranchBudgetCut] finds walking the branch from the newest
  /// end backward, so the kept tail's projected estimate stays within
  /// [tokenBudget] — overshoot bounded by one record, never one block.
  ///
  /// The dropped records stay on disk and page back lazily through
  /// [loadOlder]: `_windowTopOffset` rides [_dropOldest] up and
  /// `_hasOlder` is restored when anything was dropped (the walk may have
  /// stopped before any page — a tail window alone over the budget). The
  /// tail anchor (`_branchBottomId`, the leaf) is never touched: the cut
  /// keeps at least the newest record.
  void _trimTokenBudget(List<SessionRecord> branch, int tokenBudget) {
    final cut = projectedBranchBudgetCut(branch, tokenBudget);
    if (cut == null) return; // whole branch fits — defensive, never the stop
    final cutId = branch[cut].id;
    var dropped = 0;
    // The kept cut record is on the branch, hence resident; everything
    // file-older than it (branch records AND interleaved side-branch
    // records) leaves the window.
    while (_entries.isNotEmpty && _entries.first.id != cutId) {
      _dropOldest();
      dropped++;
    }
    if (dropped > 0) _hasOlder = true;
  }

  /// One block page-up for the boundary walk ([growOlderUntil]): a
  /// single-read strip above the window (see
  /// [SessionChunkReader.readBlockBefore]), indexed like a regular chunk.
  /// No branch join here — the walk's predicate reads the index through
  /// [getPathToRoot]; eviction stays suspended by the caller.
  Future<void> _readOlderBlock(int maxRecords, int maxBytes) async {
    final top = _windowTopOffset;
    if (top == null) {
      _hasOlder = false;
      return;
    }
    final chunk = await _reader.readBlockBefore(
      top,
      maxRecords: maxRecords,
      maxBytes: maxBytes,
      // Issue #503 round 3b: the walk crosses hundreds of ~0.75 MB
      // `model_request_summary` ledger payloads that count zero context
      // tokens — decode them header-only (data stubbed to null). The
      // ingest and scrollback paths keep full fidelity; a shallow-parsed
      // record only loses its Request-tab detail, never chain integrity.
      shallowGiantCustoms: true,
    );
    if (chunk.isEmpty) {
      // Mirrors _readOlderChunk: an empty read above the window ends the
      // walk (file top, or a torn region — degenerate, but bounded).
      _hasOlder = false;
      return;
    }
    _windowTopOffset = chunk.firstOffset;
    _hasOlder = chunk.hasOlder;
    _indexChunk(chunk, prepend: true);
    _aboveCount = _aboveCount == null
        ? null
        : _aboveCount! - chunk.entries.length;
  }

  /// One page-up pass: reads the chunk above the window, indexes it
  /// (prepended), advances the window top, and reports the connect id
  /// for the branch join. `null` when no pass applies (no history above,
  /// branch root resident, or the file top reached - `_hasOlder` then
  /// goes false).
  Future<(SessionChunk, String?)?> _readOlderChunk(
    int maxRecords,
    int maxBytes,
  ) async {
    if (!_hasOlder) return null;
    final connectId = await _branchConnectId();
    if (connectId == null) return null; // branch root is already resident
    final top = _windowTopOffset;
    if (top == null) return null;
    final chunk = await _reader.readBefore(
      top,
      maxRecords: maxRecords,
      maxBytes: maxBytes,
    );
    if (chunk.isEmpty) {
      _hasOlder = false;
      return null;
    }
    _windowTopOffset = chunk.firstOffset;
    _hasOlder = chunk.hasOlder;
    _indexChunk(chunk, prepend: true);
    _aboveCount = _aboveCount == null
        ? null
        : _aboveCount! - chunk.entries.length;
    return (chunk, connectId);
  }

  /// Pages one chunk of records back in BELOW the window — the
  /// page-down path after deep paging slid the newest side out.
  /// Returns the records that rejoin the active branch at the bottom,
  /// oldest-first (the transcript delta to append).
  Future<List<SessionRecord>> loadNewer({
    int maxRecords = defaultChunkRecords,
    int maxBytes = defaultChunkBytes,
  }) async {
    final chunk = await _reader.readForward(
      _knownFileBytes,
      maxRecords: maxRecords,
      maxBytes: maxBytes,
    );
    if (chunk.isEmpty) {
      _belowCount = 0;
      return const [];
