    // under its result tile (presentation order = call order).
    if (toolName == 'dynamic_message') {
      final presented = dynamicMessages.takePendingMarker();
      if (presented != null) {
        messages.add(
          FahChatMessage(
            role: DynamicMessagesService.markerRole,
            content: presented.title,
            data: presented.id,
