  /// Resets the whole window to [chunk] (jump / re-anchor): every
  /// structure is rebuilt, the sparse offset map keeps its history, the
  /// leaf survives.
  void _replaceWindowWithChunk(SessionChunk chunk) {
    _entries.clear();
    _offsets.clear();
    _ends.clear();
    _byId.clear();
    _appendedBelow.clear();
    _labelsById.clear();
